@@ -0,0 +1,48 @@
+// Sales from the till: each line sells `qty` of a dish and uses one portion
+// of the dish's recipe per `qty`. A ticket is recorded once; recording is
+// all or nothing for the whole set of lines (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Every recorded sale line, in id order. */
+export function listSales(store) {
+  return [...(store.data.sales ?? [])].sort((a, b) => a.id - b.id);
+}
+
+/**
+ * Records sale lines ({ row, ticket, soldAt, dishId, qty }) and consumes their ingredients at `soldAt`
+ * with the ref `sale:<ticket>`. Tickets recorded before are skipped. Throws (and changes nothing) on an
+ * unknown dish or when an item runs out, naming the line's `row`. Returns { tickets, dishes } recorded.
+ */
+export function recordSales(store, lines) {
+  const known = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const taken = new Map();
+  const planned = [];
+  for (const line of lines) {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === line.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${line.row}: unknown dish ${line.dishId}` });
+    if (known.has(line.ticket)) continue;
+    const use = scaled(getRecipe(store, dish.recipeId), line.qty).filter((u) => u.qty > 0);
+    for (const u of use) {
+      const item = getItem(store, u.itemId);
+      const available = round3(onHand(store, u.itemId) - (taken.get(u.itemId) ?? 0));
+      if (available < u.qty)
+        throw new AppError("import_not_enough_stock", { row: line.row, item: item.name, available, unit: item.unit });
+      taken.set(u.itemId, round3((taken.get(u.itemId) ?? 0) + u.qty));
+    }
+    planned.push({ line, use });
+  }
+  store.data.sales ??= [];
+  for (const { line, use } of planned) {
+    for (const u of use) consume(store, u.itemId, u.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty, use });
+  }
+  return {
+    tickets: new Set(planned.map((p) => p.line.ticket)).size,
+    dishes: planned.reduce((s, p) => s + p.line.qty, 0),
+  };
+}
